package com.rohit.inventory.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="inventory") public class Inventory extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="warehouse_id",nullable=false) private Warehouse warehouse; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="zone_id",nullable=false) private WarehouseZone zone; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) private Product product; @Column(name="on_hand_quantity",nullable=false) private BigDecimal onHandQuantity=BigDecimal.ZERO; @Column(name="reserved_quantity",nullable=false) private BigDecimal reservedQuantity=BigDecimal.ZERO; @Column(name="damaged_quantity",nullable=false) private BigDecimal damagedQuantity=BigDecimal.ZERO; @Column(name="available_quantity",insertable=false,updatable=false) private BigDecimal availableQuantity; @Version private Long version; public Warehouse getWarehouse(){return warehouse;} public WarehouseZone getZone(){return zone;} public Product getProduct(){return product;} public BigDecimal getOnHandQuantity(){return onHandQuantity;} public BigDecimal getReservedQuantity(){return reservedQuantity;} public BigDecimal getDamagedQuantity(){return damagedQuantity;} public BigDecimal getAvailableQuantity(){return availableQuantity==null?onHandQuantity.subtract(reservedQuantity):availableQuantity;} public Long getVersion(){return version;} public void setWarehouse(Warehouse v){warehouse=v;} public void setZone(WarehouseZone v){zone=v;} public void setProduct(Product v){product=v;} public void setOnHandQuantity(BigDecimal v){onHandQuantity=v;} public void setReservedQuantity(BigDecimal v){reservedQuantity=v;} public void setDamagedQuantity(BigDecimal v){damagedQuantity=v;} }
